import json, math
from decimal import Decimal
from itertools import combinations
from urban_micro import window_compare

def row(t,c,d): return (t,c,0.0,0.0,float(d),0.0,0.0,0.0)
edges = [("a1","a2"),("b1","b2"),("c1","c2")]
labels = {f"{x}{i}": x.upper() for x in ("a","b","c") for i in (1,2)}
vals = {
  0:    {"a1":0,"a2":0,"b1":0,"b2":0,"c1":0,"c2":0},
  3600: {"a1":4,"a2":0,"b1":2,"b2":0,"c1":1,"c2":0},
  7200: {"a1":0,"a2":4,"b1":0,"b2":2,"c1":0,"c2":3},
  10800:{"a1":5,"a2":1,"b1":1,"b2":3,"c1":2,"c2":0},
}
details = [row(t,c,v) for t,cs in vals.items() for c,v in cs.items()]
windows = {0:"O",3600:"W1",7200:"W2",10800:"W2"}
out = window_compare(details, edges, [1], labels, windows, alpha=0.9)
res = json.loads(out)

# Derive reference x exactly: x_B(edge)=(d_B[u]-d_prev[u])-(d_B[v]-d_prev[v])
def xvals(B, edge):
    u,v=edge; cur,prev=vals[B],vals[B-3600]
    return Decimal(cur[u]-prev[u]-(cur[v]-prev[v]))
win_buckets={"W1":[3600],"W2":[7200,10800]}
samples={w:{l.upper():[xvals(B,e) for B in bs for e in edges if labels[e[0]]==l.upper()]
            for l in ("a","b","c")} for w,bs in win_buckets.items()}

def perm_p(sa,sb):
    na,nb=len(sa),len(sb); pooled=sa+sb; tot=sum(pooled)
    thr=abs(sum(sa)*nb-sum(sb)*na); hits=0
    for combo in combinations(range(na+nb),na):
        pa=sum(pooled[i] for i in combo); pb=tot-pa
        if abs(pa*nb-pb*na)>=thr: hits+=1
    return Decimal(hits)/Decimal(math.comb(na+nb,na))

recs=[]
for w in ("W1","W2"):
    labs=sorted(samples[w])
    for i,x in enumerate(labs):
        for y in labs[i+1:]:
            recs.append([w,x,y,perm_p(samples[w][x],samples[w][y])])
N=len(recs)
ranked=sorted(range(N),key=lambda i:(recs[i][3],recs[i][0],recs[i][1],recs[i][2]))
run=Decimal(1); q={}
for r in range(N,0,-1):
    i=ranked[r-1]; run=min(run,Decimal(N)*recs[i][3]/r)
    q[(recs[i][0],recs[i][1],recs[i][2])]=run
pmap={(w,a,b):p for w,a,b,p in recs}
for g in res["groups"]:
    for c in g["comparisons"]:
        for lo in c["lags"]:
            k=(g["key"],c["a"],c["b"])
            assert f"{lo['p']:.6f}"==f"{float(pmap[k]):.6f}",(k,lo['p'],pmap[k])
            assert f"{lo['q']:.6f}"==f"{float(q[k]):.6f}",(k,lo['q'],q[k])
            assert lo["reject"]==(q[k]<=Decimal("0.9"))
print("global BH cross-check OK, N =",N)
for g in res["groups"]:
    for c in g["comparisons"]:
        lo=c["lags"][0]
        print(g["key"],c["a"],c["b"],"n",lo["n_a"],lo["n_b"],"diff",lo["diff"],"p",lo["p"],"q",lo["q"],"rej",lo["reject"])
EOF
